#!/usr/bin/env python3
"""Promote the index-7/2 Lane–Emden headline, its simulator, certificates and existence proof from
Work/Math to Checked/Math (run 2026-11-19T2228Z; promote_le52.py of run 2026-11-19T1628Z with the index changed and the
data in four parts; LEGStart is already in Checked). The headline docstring is the promoted index-five-halves one with
the numbers changed (its wording passed the claim-vocabulary checks), written into the Work file too.

Mechanical copy: namespaces Work.Math -> Checked.Math, `import Mathlib` -> specific modules, module docs
replaced by number-free text (check_prose rule 7). Statements and proofs otherwise byte-identical."""
import pathlib
ROOT = pathlib.Path(__file__).resolve().parents[3]
W, C = ROOT / "Work/Math", ROOT / "Checked/Math"
MODS = ["LE72Cell", "LE72CellQ", "LE72Glue", "LE72QDataP0", "LE72QDataP1", "LE72QDataP2", "LE72QData", "LE72Chain",
        "LaneEmden72", "LE72ExistsLeft", "LE72ExistsRight", "LE72Exists"]
G = "`runs/2026-11-19T2228Z/scripts/emit_le72.py`"
P = "Promoted verbatim from `Work/Math/{m}.lean`."
DATA = "the singular start and the validated cells of the Lane–Emden chain of index seven halves as data; every side condition, defect bound and link decided by kernel evaluation over the rationals, one declaration per segment of cells."
DOCS = {
 "LE72Cell": "Lane–Emden equation of index seven halves: the nonlinearity θ to the power seven halves as `g72 θ`, the seventh power of the square root (equal to Mathlib's real power for every real θ, `rpow72_eq`), its Lipschitz bound on a slab (`g72_lip`), the closeness of `g72 x` to the seventh power of `y` from a certificate that the square of `y` is close to `x` (`g72_close`), and the validated cell step `cell` (Grönwall, generic tube lemma `Checked.Math.LENCell.tube_cell_t`).",
 "LE72CellQ": "Lane–Emden equation of index seven halves: the validated cells of `Checked.Math.LE72Cell.cell` checked by kernel evaluation. All side conditions and both defect bounds of a cell are one proposition over the rationals (`CellProp`); the power of the Taylor polynomial is replaced in the defect by the seventh power of a polynomial `pw` whose square is certified close to it and which is bounded away from zero, and in a cell next to the zero of θ (`pw` empty) it is bounded crudely. The chain lemmas are those of `Checked.Math.LENCellQ` with this field.",
 "LE72Glue": "Lane–Emden equation of index seven halves: the singular start (`start72`, the generic start of `Checked.Math.LEGStart` with a residual certified through the square-root polynomial) and the last cell (`last72`: sign change of θ, φ negative, bounds on the mass factor), each from one proposition over the rationals decided by kernel evaluation; `qeqB` compares coefficient lists with order relations only.",
 "LE72QDataP0": f"Generated by {G}, first of four parts: {DATA}",
 "LE72QDataP1": f"Generated by {G}, second of four parts: {DATA}",
 "LE72QDataP2": f"Generated by {G}, third of four parts: {DATA}",
 "LE72QData": f"Generated by {G}, last of four parts (the data are split because one module of all cells ran out of memory locally): {DATA}",
 "LE72Chain": f"Generated by {G}: chaining of the singular start, the kernel-checked segments and the last cell of the Lane–Emden chain of index seven halves.",
 "LE72ExistsLeft": "Lane–Emden equation of index seven halves, existence near the centre: Banach fixed point of the scaled Volterra map with the power seven halves clamped closer to one than in the index-three construction `Checked.Math.LEExistsLeft`, so that the index-three constants bound it.",
 "LE72ExistsRight": "Lane–Emden equation of index seven halves, existence away from the centre: Picard–Lindelöf for the clamped field; the clamped energy is nonincreasing and the potential part is not negative, so the clamp on φ stays inactive, and the bound on θ' keeps the clamp on θ inactive (adapted from `Checked.Math.LEExistsRight`).",
 "LE72Exists": "Lane–Emden equation of index seven halves: existence of a solution meeting every hypothesis of `Checked.Math.LaneEmden72.laneEmden72_constants` (left piece by a fixed point, right piece by Picard–Lindelöf for the clamped field with the clamps inactive by the energy, glued).",
}
NEWDOC = """/-- Lane–Emden equation θ'' + (2/ξ)θ' + θ ^ (7/2) = 0: for every solution θ on (0, 10] with
θ(0) = 1, θ differentiable on [0, 10] with derivative φ, and φ continuous at 0, there is a zero ξ₁ of
θ with 9.53580534 ≤ ξ₁ ≤ 9.53580535 and θ > 0 on [0, ξ₁), at which −ξ₁² θ'(ξ₁) lies between
1.89055709 and 1.89055710 and ξ₁³/(3 · (−ξ₁² θ'(ξ₁))) lies between 152.8836627 and 152.8836632. -/"""
WF = W / "LaneEmden72.lean"
w = WF.read_text()
if "/-- Lane–Emden equation of index 7/2" in w:   # first run only (the freeze's docstring)
    a = w.index("/-- Lane–Emden equation of index 7/2"); b = w.index("-/", a) + 2
    w = w[:a] + NEWDOC + w[b:]
assert NEWDOC in w
w = w.replace("its fourth derivative in θ blows up there", "its fourth derivative in θ is unbounded there")
WF.write_text(w)
for m in MODS:
    s = (W / f"{m}.lean").read_text()
    s = s.replace("Work.Math.", "Checked.Math.")
    assert "Work." not in s, m
    if m == "LaneEmden72":
        s = s.replace("import Mathlib\n", "import Mathlib.Analysis.Calculus.Deriv.MeanValue\nimport Mathlib.Topology.Order.IntermediateValue\n", 1)
        s = s.replace("frozen before proof, run 2026-11-19T2228Z", "frozen before proof in `Work/Math/LaneEmden72.lean`, statement promoted\nbyte-identical")
        s = s.replace("`Checked.Math.LE72Exists.exists_solution` (checked in a separate module).",
                      "`Checked.Math.LE72Exists.exists_solution` (non-vacuity witness in `Checked/Trust/Witnesses.lean`).")
        s = s.replace("import Checked.Math.LE72Chain\n", "import Checked.Math.LE72Chain\n", 1)
        assert "to do" not in s and "non-vacuity witness" in s
    else:
        assert "import Mathlib\n" not in s, m
        i = s.index("/-!")
        j = s.index("-/", i) + 2
        s = s[:i] + "/-! " + DOCS[m] + " " + P.format(m=m) + " -/" + s[j:]
    (C / f"{m}.lean").write_text(s)
    print("wrote", m)
